// ---------------------------------------------------------------- store (device-only; every read/write guarded)
const LS=k=>{try{return JSON.parse(localStorage.getItem(k))}catch(e){return null}},SS=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v))}catch(e){}};
try{if(!localStorage.getItem("itanva.migrated")){for(const k of Object.keys(localStorage))if(k.startsWith("itanva."))localStorage.setItem("itanva."+k.slice(6),localStorage.getItem(k));localStorage.setItem("itanva.migrated","1")}}catch(e){}
let L=LS("itanva.lang")||((navigator.language||"fr").slice(0,2)==="en"?"en":"fr");
const t=k=>I[L][k];
const prefs=Object.assign({size:18,lh:1.6,font:"serif",theme:"light",mode:"paged",wpm:230,focus:false},LS("itanva.prefs")||{});
let progress=LS("itanva.progress")||{};
let marks=LS("itanva.marks")||{};
let notes=LS("itanva.notes")||{};           // id -> [{ch,pi,text,note,c,ts}]
let shelf=Object.assign({toread:[],fav:[],finished:[]},LS("itanva.shelf")||{});
let profile=Object.assign({interests:[],goal:null,onboarded:false,seen:0},LS("itanva.profile")||{});
let stats=Object.assign({days:{}},LS("itanva.stats")||{});   // days: {"2026-10-30":{min:12,books:[id],ch:3}}
let events=LS("itanva.events")||[];        // first-party, device-only event log (see docs/ANALYTICS.md)
const track=(e,d)=>{events.push(Object.assign({e,t:Date.now()},d||{}));if(events.length>600)events=events.slice(-600);SS("itanva.events",events)};
// ---------------------------------------------------------------- sync (optional account: name + 4-digit PIN)
const SYNC_URL="https://itanva-sync.onrender.com";
let account=LS("itanva.account")||null;let syncTimer=null,syncState="idle";
const SYNC_KEYS=["itanva.progress","itanva.shelf","itanva.notes","itanva.marks","itanva.stats","itanva.profile","itanva.prefs"];
const _SS=SS;const SSs=(k,v)=>{_SS(k,v);if(account&&SYNC_KEYS.includes(k))scheduleSync()};
function snapshot(){return{v:1,at:Date.now(),progress,shelf,notes,marks,stats,profile,prefs:{size:prefs.size,lh:prefs.lh,font:prefs.font,theme:prefs.theme,mode:prefs.mode,wpm:prefs.wpm}}}
function mergeState(r){if(!r)return;for(const [id,p] of Object.entries(r.progress||{})){const l=progress[id];if(!l||(p.at||0)>(l.at||0)){progress[id]=Object.assign({},p,{done:[...new Set([...(l&&l.done||[]),...(p.done||[])])]})}else l.done=[...new Set([...(l.done||[]),...(p.done||[])])]}
 for(const k of ["toread","fav","finished"])shelf[k]=[...new Set([...(shelf[k]||[]),...((r.shelf||{})[k]||[])])];
 for(const [id,arr] of Object.entries(r.notes||{})){const seen=new Set((notes[id]||[]).map(h=>h.ts));notes[id]=[...(notes[id]||[]),...arr.filter(h=>!seen.has(h.ts))]}
 for(const [id,arr] of Object.entries(r.marks||{})){const seen=new Set((marks[id]||[]).map(h=>h.ts));marks[id]=[...(marks[id]||[]),...arr.filter(h=>!seen.has(h.ts))].slice(0,30)}
 for(const [d,x] of Object.entries((r.stats||{}).days||{})){const l=stats.days[d];if(!l)stats.days[d]=x;else{l.min=Math.max(l.min||0,x.min||0);l.ch=Math.max(l.ch||0,x.ch||0);l.books=[...new Set([...(l.books||[]),...(x.books||[])])];if(x.fin)l.fin=[...new Set([...(l.fin||[]),...x.fin])]}}
 if(r.profile&&(!profile.onboarded||(r.profile.interests||[]).length>profile.interests.length))profile=Object.assign(profile,r.profile,{seen:profile.seen});
 if(r.prefs&&!LS("itanva.prefs"))Object.assign(prefs,r.prefs);
 [["itanva.progress",progress],["itanva.shelf",shelf],["itanva.notes",notes],["itanva.marks",marks],["itanva.stats",stats],["itanva.profile",profile],["itanva.prefs",prefs]].forEach(([k,v])=>_SS(k,v))}
async function api(path,body,method){const r=await fetch(SYNC_URL+path,{method:method||(body?"POST":"GET"),headers:Object.assign({"Content-Type":"application/json"},account?{Authorization:"Bearer "+account.token}:{}),body:body?JSON.stringify(body):undefined});let j=null;try{j=await r.json()}catch(e){}if(!r.ok){const err=new Error((j&&j.error)||"net");err.code=(j&&j.error)||"net";throw err}return j}
function scheduleSync(){clearTimeout(syncTimer);syncTimer=setTimeout(pushState,8000)}
async function pushState(){if(!account)return;syncState="syncing";renderSync();try{await api("/api/state",{state:snapshot()},"PUT");syncState="ok";account.last=Date.now();_SS("itanva.account",account)}catch(e){syncState="err";if(e.code==="no_session"){account=null;_SS("itanva.account",null)}}renderSync()}
async function pullState(){if(!account)return;try{const j=await api("/api/state");if(j&&j.state){mergeState(j.state);syncState="ok"}}catch(e){syncState="err";if(e.code==="no_session"){account=null;_SS("itanva.account",null)}}renderSync()}
function renderSync(){const el=$("#syncst");if(!el)return;el.textContent=syncState==="syncing"?t("acc_syncing"):syncState==="ok"?t("acc_sync")+(account&&account.last?" · "+new Date(account.last).toLocaleTimeString(L,{hour:"2-digit",minute:"2-digit"}):""):syncState==="err"?t("acc_err").net:""}
