function accountSheet(mode){mode=mode||"create";const d=sheet(`<h2>${t("acc_h")}</h2><p class="muted small">${t("acc_sub")}</p>
 <div class="stabs" role="tablist" style="margin-top:10px"><button data-m="create" class="${mode==="create"?"on":""}">${t("acc_create")}</button><button data-m="login" class="${mode==="login"?"on":""}">${t("acc_login")}</button></div>
 <form id="accf" autocomplete="off"><label class="lab" for="an">${t("acc_name")}</label><input id="an" class="inp" maxlength="24" autocomplete="username" required><label class="lab" for="ap">${t("acc_pin")}</label><input id="ap" class="inp" inputmode="numeric" pattern="[0-9]{4}" maxlength="4" autocomplete="current-password" type="password" required style="letter-spacing:8px;font-size:22px;width:9em">
 <p class="small muted" id="acnote">${mode==="create"?t("acc_note"):""}</p><p class="err" id="acerr" hidden></p><div class="opts" style="margin-top:12px"><button class="btn" id="acgo" type="submit">${mode==="create"?t("acc_create"):t("acc_login")}</button></div></form>`,{nofocus:true});
 d.querySelectorAll("[data-m]").forEach(b=>b.onclick=()=>accountSheet(b.dataset.m));
 d.querySelector("#accf").onsubmit=async e=>{e.preventDefault();const name=d.querySelector("#an").value.trim(),pin=d.querySelector("#ap").value;const err=d.querySelector("#acerr"),go=d.querySelector("#acgo");err.hidden=true;go.disabled=true;go.textContent="…";
  try{if(mode==="create"){const j=await api("/api/signup",{name,pin,state:snapshot()});account={token:j.token,name:j.name,last:Date.now()};_SS("itanva.account",account);syncState="ok";toast(t("acc_ok"))}
   else{const j=await api("/api/login",{name,pin});account={token:j.token,name:j.name,last:Date.now()};_SS("itanva.account",account);mergeState(j.state);syncState="ok";toast(t("acc_in"));scheduleSync()}
   track("account",{m:mode});d.remove();route()}
  catch(ex){err.textContent=t("acc_err")[ex.code]||t("acc_err").net;err.hidden=false;go.disabled=false;go.textContent=mode==="create"?t("acc_create"):t("acc_login")}};
 d.querySelector("#an").focus()}
async function logout(){try{await api("/api/logout",{})}catch(e){}account=null;_SS("itanva.account",null);syncState="idle";toast(t("acc_out"));route()}
const accountCard=()=>account?`<div class="goal"><div style="flex:1"><div class="t">${t("acc_as")(esc(account.name))}</div><div class="s" id="syncst"></div></div><button class="pill" id="aclogout">${t("acc_logout")}</button></div>`:`<div class="goal"><div style="flex:1"><div class="t">${t("acc_h")}</div><div class="s">${t("acc_sub")}</div></div></div><div class="opts" style="margin-top:8px"><button class="btn" id="accreate">${t("acc_create")}</button><button class="btn sec" id="aclogin">${t("acc_login")}</button></div>`;
