function finishBook(id,manual){if(shelf.finished.includes(id))return;shelf.finished.push(id);const i=shelf.toread.indexOf(id);if(i>=0)shelf.toread.splice(i,1);SSs("itanva.shelf",shelf);const d=stats.days[today()]||(stats.days[today()]={min:0,books:[],ch:0});(d.fin=d.fin||[]).push(id);SSs("itanva.stats",stats);track("book_done",{id,manual:!!manual});
 const b=BOOKS[id];const d2=sheet(`<div class="cele"><div class="big">📚</div><h2>${t("book_done_t")}</h2><p class="muted">${t("book_done_s")}</p><p style="margin:14px 0"><b>${esc(shortTitle(b.title))}</b> · ${esc(b.author)}</p><div class="opts" style="justify-content:center"><button class="btn" id="cs">${t("share")}</button><a class="btn sec" href="#/catalogue?sort=reco">${t("reco_h")}</a></div></div>`);d2.querySelector("#cs").onclick=()=>shareCard(b)}
