async function shareCard(b){const d=sheet(`<div class="share" style="display:flex;flex-direction:column;gap:12px;align-items:center"><h2>${t("share_t")}</h2><canvas width="1080" height="1350" id="shc" style="width:min(100%,250px);height:auto;border-radius:10px;box-shadow:var(--shadow)"></canvas><div class="opts" style="justify-content:center"><button class="btn" id="shs">${t("share")}</button><button class="btn sec" id="shd">${t("share_dl")}</button><button class="btn sec" id="shl">${t("share_link")}</button></div></div>`);
 const cv=d.querySelector("#shc"),x=cv.getContext("2d");const k=coverKey(b),[c1]=PAL[k];try{await document.fonts.load("700 60px Fraunces")}catch(e){}
 x.fillStyle="#F7F3E9";x.fillRect(0,0,1080,1350);x.fillStyle=c1;x.fillRect(0,0,1080,760);
 const img=new Image();const url=URL.createObjectURL(new Blob([coverSVG(b)],{type:"image/svg+xml"}));await new Promise(r=>{img.onload=r;img.onerror=r;img.src=url});
 x.save();x.shadowColor="rgba(0,0,0,.45)";x.shadowBlur=40;x.shadowOffsetY=20;x.drawImage(img,340,100,400,600);x.restore();URL.revokeObjectURL(url);
 x.fillStyle="#182D3B";x.font="700 34px system-ui,sans-serif";x.fillText(t("reading_now").toUpperCase(),72,850);x.font="700 64px Fraunces,Georgia,serif";const lines=wrap(shortTitle(b.title),26,2);lines.forEach((l,i)=>x.fillText(l,72,930+i*72));
 x.font="400 40px system-ui,sans-serif";x.fillStyle="#56636E";x.fillText(b.author.split(",")[0],72,930+lines.length*72+10);
 const p=progress[b.id];if(p){x.fillStyle="#E3DAC6";x.fillRect(72,1160,936,14);x.fillStyle="#287D64";x.fillRect(72,1160,936*p.pct/100,14);x.fillStyle="#56636E";x.font="400 32px system-ui,sans-serif";x.fillText(`${p.pct} %`,72,1215)}
 x.fillStyle="#9E5226";x.font="700 40px Fraunces,Georgia,serif";x.fillText("Itanva",72,1300);x.fillStyle="#56636E";x.font="400 30px system-ui,sans-serif";x.fillText(SITE.replace(/^https?:\/\//,""),200,1300);
 const link=SITE+"livre/"+b.id+".html";const text=t("share_msg")(shortTitle(b.title),b.author.split(",")[0])+" "+link;
 const blob=await new Promise(r=>cv.toBlob(r,"image/png"));const file=blob&&new File([blob],"itanva.png",{type:"image/png"});track("share",{id:b.id});
 d.querySelector("#shs").onclick=async()=>{try{if(file&&navigator.canShare&&navigator.canShare({files:[file]}))await navigator.share({files:[file],text});else if(navigator.share)await navigator.share({text,url:link});else throw 0}catch(e){try{await navigator.clipboard.writeText(text);toast(t("copied"))}catch(_){}}};
 d.querySelector("#shd").onclick=()=>{if(!blob)return;const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="bibli-"+b.id+".png";a.click()};
 d.querySelector("#shl").onclick=async()=>{try{await navigator.clipboard.writeText(link);toast(t("copied"))}catch(e){prompt("",link)}}}
// ---------------------------------------------------------------- onboarding
function onboarding(goalOnly){let step=goalOnly?2:1;const sel=new Set(profile.interests);
 const render=()=>{const d=sheet(step===1?`<div class="onb"><h2>${t("onb_h")}</h2><p class="muted small">${t("onb_s")}</p><div class="opts" style="margin:10px 0">${Object.keys(t("genres")).map(g=>`<button class="pill ${sel.has(g)?"on":""}" data-g="${g}" aria-pressed="${sel.has(g)}">${t("genres")[g]}</button>`).join("")}</div><div class="opts"><button class="btn" id="nx">${L==="fr"?"Suivant":"Next"}</button><button class="btn ghost" id="sk">${t("skip")}</button></div></div>`
  :`<div class="onb"><h2>${t("onb_goal")}</h2><p class="muted small">${t("device")}.</p><div class="opts" style="margin:10px 0">${[5,10,20,0].map(g=>`<button class="pill ${profile.goal===g?"on":""}" data-goal="${g}">${t("goals")[g]}</button>`).join("")}</div><div class="opts"><button class="btn" id="ok">${t("ok")}</button><button class="btn ghost" id="sk">${t("skip")}</button></div></div>`,{sticky:true});
  d.querySelectorAll("[data-g]").forEach(b=>b.onclick=()=>{const g=b.dataset.g;sel.has(g)?sel.delete(g):sel.add(g);b.classList.toggle("on",sel.has(g));b.setAttribute("aria-pressed",sel.has(g))});
  d.querySelectorAll("[data-goal]").forEach(b=>b.onclick=()=>{profile.goal=+b.dataset.goal;d.querySelectorAll("[data-goal]").forEach(x=>x.classList.toggle("on",+x.dataset.goal===profile.goal))});
  const fin=()=>{profile.interests=[...sel];profile.onboarded=true;SSs("itanva.profile",profile);track("onboard",{n:sel.size,goal:profile.goal});d.remove();route()};
  const nx=d.querySelector("#nx");if(nx)nx.onclick=()=>{step=2;render()};const ok=d.querySelector("#ok");if(ok)ok.onclick=fin;d.querySelector("#sk").onclick=()=>{profile.onboarded=true;SSs("itanva.profile",profile);d.remove()}};
 render()}
