 const voices=speechSynthesis.getVoices().filter(v=>v.lang.toLowerCase().startsWith(lang));const paras=[...cols.querySelectorAll("h3,p")].map(p=>p.textContent.trim()).filter(Boolean);if(!paras.length)return;
