 if(slug){const p=posts.find(x=>x.slug===slug);if(!p)return app.innerHTML=errorBox();app.innerHTML=`<p class="small"><a href="#/blog">‹ ${t("blog_h")}</a></p><h1 style="margin:8px 0">${esc(p.title)}</h1><p class="small muted"><time>${p.date}</time></p><div class="article" style="margin-top:14px">${p.html}</div>`;return}
